contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint lockTime) public payable {
        require(amount > 0);
        require(address(this).balance >= amount * 2);
        c.SetMinSum(0);
        c.Initialized();
        c.Put{value: amount}(lockTime);
        (uint balBefore, ) = c.Acc(address(this));
        assert(balBefore == amount);
        // fast-forward: lockTime must be 0 so timestamp > unlockTime may still fail
        // instead just collect the zero-lock portion: use lockTime = 0 case
        bool reverted;
        if (lockTime == 0) {
            try c.Collect(amount) { reverted = false; }
            catch { reverted = true; }
            (uint balAfter, ) = c.Acc(address(this));
            assert(!reverted && balAfter == 0);
        } else {
            try c.Collect(amount) { reverted = false; }
            catch { reverted = true; }
            (uint balAfter2, ) = c.Acc(address(this));
            assert(reverted && balAfter2 == amount);
        }
    }
    receive() external payable {}
}

